import{_ as n,c as s,o as t,ag as e}from"./chunks/framework.CMajxlqO.js";const g=JSON.parse('{"title":"OB, FB, FC – skillnader","description":"","frontmatter":{},"headers":[],"relativePath":"04-programmering/ob-fb-fc.md","filePath":"04-programmering/ob-fb-fc.md","lastUpdated":1768315788000}'),r={name:"04-programmering/ob-fb-fc.md"};function l(i,a,p,o,d,c){return t(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="ob-fb-fc-–-skillnader" tabindex="-1">OB, FB, FC – skillnader <a class="header-anchor" href="#ob-fb-fc-–-skillnader" aria-label="Permalink to &quot;OB, FB, FC – skillnader&quot;">​</a></h1><p>I TIA Portal organiseras PLC-program i olika typer av block: <strong>Organization Blocks (OB)</strong>, <strong>Function Blocks (FB)</strong> och <strong>Functions (FC)</strong>. Att förstå skillnaderna mellan dessa är avgörande för att strukturera din kod korrekt och effektivt.</p><h2 id="organization-blocks-ob" tabindex="-1">Organization Blocks (OB) <a class="header-anchor" href="#organization-blocks-ob" aria-label="Permalink to &quot;Organization Blocks (OB)&quot;">​</a></h2><h3 id="vad-ar-en-ob" tabindex="-1">Vad är en OB? <a class="header-anchor" href="#vad-ar-en-ob" aria-label="Permalink to &quot;Vad är en OB?&quot;">​</a></h3><p>Organization Blocks är <strong>ingångspunkter</strong> för PLC-programmet. De anropas automatiskt av operativsystemet vid specifika händelser.</p><h3 id="vanliga-ob-typer" tabindex="-1">Vanliga OB-typer <a class="header-anchor" href="#vanliga-ob-typer" aria-label="Permalink to &quot;Vanliga OB-typer&quot;">​</a></h3><h4 id="ob1-main-cycle-huvudcykel" tabindex="-1">OB1 - Main Cycle (Huvudcykel) <a class="header-anchor" href="#ob1-main-cycle-huvudcykel" aria-label="Permalink to &quot;OB1 - Main Cycle (Huvudcykel)&quot;">​</a></h4><ul><li><strong>Funktion:</strong> Exekveras cykliskt, om och om igen</li><li><strong>Användning:</strong> Huvudprogrammet - här anropas dina FB och FC</li><li><strong>Cykeltid:</strong> Typiskt 10-100 ms beroende på programstorlek</li><li><strong>Obligatorisk:</strong> Ja, varje projekt måste ha minst OB1</li></ul><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Start] → [OB1] → [Exekvera kod] → [Uppdatera I/O] → [OB1] → ...</span></span></code></pre></div><h4 id="ob100-startup-uppstart" tabindex="-1">OB100 - Startup (Uppstart) <a class="header-anchor" href="#ob100-startup-uppstart" aria-label="Permalink to &quot;OB100 - Startup (Uppstart)&quot;">​</a></h4><ul><li><strong>Funktion:</strong> Körs EN GÅNG vid uppstart (Warm restart)</li><li><strong>Användning:</strong> Initiering av variabler, nollställning, startvärden</li><li><strong>Exempel:</strong> Sätt standardhastighet, nollställ räknare, ladda recept</li></ul><h4 id="ob35-ob38-cyclic-interrupts-cykliska-avbrott" tabindex="-1">OB35/OB38 - Cyclic Interrupts (Cykliska avbrott) <a class="header-anchor" href="#ob35-ob38-cyclic-interrupts-cykliska-avbrott" aria-label="Permalink to &quot;OB35/OB38 - Cyclic Interrupts (Cykliska avbrott)&quot;">​</a></h4><ul><li><strong>Funktion:</strong> Körs med <strong>exakt tidsintervall</strong> (t.ex. 100 ms, 1 s)</li><li><strong>Användning:</strong> Tidskritisk styrning, PID-reglering, samplingmätning</li><li><strong>Fördel:</strong> Oberoende av OB1:s cykeltid</li></ul><h4 id="ob82-diagnostic-interrupt" tabindex="-1">OB82 - Diagnostic Interrupt <a class="header-anchor" href="#ob82-diagnostic-interrupt" aria-label="Permalink to &quot;OB82 - Diagnostic Interrupt&quot;">​</a></h4><ul><li><strong>Funktion:</strong> Anropas vid diagnostiklarm (t.ex. modulfel)</li><li><strong>Användning:</strong> Felhantering, varningar, säkerhetsåtgärder</li></ul><h4 id="ob83-pull-plug-interrupt" tabindex="-1">OB83 - Pull/Plug Interrupt <a class="header-anchor" href="#ob83-pull-plug-interrupt" aria-label="Permalink to &quot;OB83 - Pull/Plug Interrupt&quot;">​</a></h4><ul><li><strong>Funktion:</strong> Anropas när modul tas bort eller sätts i (hot-plug)</li><li><strong>Användning:</strong> Hantera dynamiska hårdvaruändringar</li></ul><h3 id="nar-ska-du-anvanda-ob" tabindex="-1">När ska du använda OB? <a class="header-anchor" href="#nar-ska-du-anvanda-ob" aria-label="Permalink to &quot;När ska du använda OB?&quot;">​</a></h3><p>✅ <strong>Använd OB:</strong></p><ul><li>När operativsystemet ska anropa koden automatiskt</li><li>För specifika händelser (startup, errors, cyclic interrupts)</li><li>Som ingångspunkt till ditt program (OB1)</li></ul><p>❌ <strong>Använd INTE OB:</strong></p><ul><li>För återanvändbar kod (använd FB/FC istället)</li><li>För komplex logik (håll OB:er korta och tydliga)</li></ul><h2 id="function-blocks-fb" tabindex="-1">Function Blocks (FB) <a class="header-anchor" href="#function-blocks-fb" aria-label="Permalink to &quot;Function Blocks (FB)&quot;">​</a></h2><h3 id="vad-ar-en-fb" tabindex="-1">Vad är en FB? <a class="header-anchor" href="#vad-ar-en-fb" aria-label="Permalink to &quot;Vad är en FB?&quot;">​</a></h3><p>Function Blocks är <strong>återanvändbara kodblock med eget minne</strong>. Varje FB har en associerad <strong>Instance Data Block (DB)</strong> som lagrar dess data mellan anrop.</p><h3 id="egenskaper" tabindex="-1">Egenskaper <a class="header-anchor" href="#egenskaper" aria-label="Permalink to &quot;Egenskaper&quot;">​</a></h3><p>✅ <strong>Har eget minne</strong> - Data behålls mellan anrop ✅ <strong>Kan ha flera instanser</strong> - Samma FB kan användas för flera objekt ✅ <strong>Stöder komplexa datatyper</strong> - Strukturer, arrayer, timers, counters</p><h3 id="exempel-motor-styrning" tabindex="-1">Exempel: Motor-styrning <a class="header-anchor" href="#exempel-motor-styrning" aria-label="Permalink to &quot;Exempel: Motor-styrning&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FUNCTION_BLOCK &quot;FB_Motor&quot;</span></span>
<span class="line"><span>{ S7_Optimized_Access := &#39;TRUE&#39; }</span></span>
<span class="line"><span>VAR_INPUT</span></span>
<span class="line"><span>    Start : Bool;      // Startkommando</span></span>
<span class="line"><span>    Stop : Bool;       // Stoppkommando</span></span>
<span class="line"><span>    Speed : Int;       // Önskad hastighet (0-100%)</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>VAR_OUTPUT</span></span>
<span class="line"><span>    Running : Bool;    // Motor igång</span></span>
<span class="line"><span>    Fault : Bool;      // Fel</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>VAR</span></span>
<span class="line"><span>    RunTimer : TON;    // Timer för uppstartssekven</span></span>
<span class="line"><span>    RunTime : Time;    // Total körtid</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BEGIN</span></span>
<span class="line"><span>    // Logik för motorstyrning</span></span>
<span class="line"><span>    IF Start AND NOT Fault THEN</span></span>
<span class="line"><span>        Running := TRUE;</span></span>
<span class="line"><span>    END_IF;</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    IF Stop OR Fault THEN</span></span>
<span class="line"><span>        Running := FALSE;</span></span>
<span class="line"><span>    END_IF;</span></span>
<span class="line"><span>END_FUNCTION_BLOCK</span></span></code></pre></div><h3 id="instansiering-i-ob1" tabindex="-1">Instansiering i OB1 <a class="header-anchor" href="#instansiering-i-ob1" aria-label="Permalink to &quot;Instansiering i OB1&quot;">​</a></h3><p>För att använda en FB måste du skapa en <strong>instans</strong> (Instance DB):</p><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// I OB1:</span></span>
<span class="line"><span>&quot;DB_Motor1&quot;(Start := %I0.0,</span><span>      // Knapp för start</span></span>
<span class="line"><span>            Stop := %I0.1,        // Knapp för stopp</span></span>
<span class="line"><span>            Speed := 75);         // 75% hastighet</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Resultat:</span></span>
<span class="line"><span>%Q0.0 := &quot;DB_Motor1&quot;.Running;</span><span>     // Styr motorutgång</span></span></code></pre></div><h3 id="flera-instanser-av-samma-fb" tabindex="-1">Flera instanser av samma FB <a class="header-anchor" href="#flera-instanser-av-samma-fb" aria-label="Permalink to &quot;Flera instanser av samma FB&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Motor 1</span></span>
<span class="line"><span>&quot;DB_Motor1&quot;(Start := %I0.0, Stop := %I0.1);</span></span>
<span class="line"><span>%Q0.0 := &quot;DB_Motor1&quot;.Running;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Motor 2 (samma FB, egen data!)</span></span>
<span class="line"><span>&quot;DB_Motor2&quot;(Start := %I0.2, Stop := %I0.3);</span></span>
<span class="line"><span>%Q0.1 := &quot;DB_Motor2&quot;.Running;</span></span></code></pre></div><h3 id="nar-ska-du-anvanda-fb" tabindex="-1">När ska du använda FB? <a class="header-anchor" href="#nar-ska-du-anvanda-fb" aria-label="Permalink to &quot;När ska du använda FB?&quot;">​</a></h3><p>✅ <strong>Använd FB:</strong></p><ul><li>När du behöver lagra data mellan anrop (timers, counters, tillstånd)</li><li>För objektorienterad programmering (motor, ventil, pump)</li><li>När samma logik behövs på flera ställen (flera motorer, pumpar, etc.)</li><li>För komplex logik med tillståndsmaskiner</li></ul><h2 id="functions-fc" tabindex="-1">Functions (FC) <a class="header-anchor" href="#functions-fc" aria-label="Permalink to &quot;Functions (FC)&quot;">​</a></h2><h3 id="vad-ar-en-fc" tabindex="-1">Vad är en FC? <a class="header-anchor" href="#vad-ar-en-fc" aria-label="Permalink to &quot;Vad är en FC?&quot;">​</a></h3><p>Functions är <strong>återanvändbara kodblock UTAN eget minne</strong>. De fungerar som rena matematiska funktioner - samma ingångar ger alltid samma utgångar.</p><h3 id="egenskaper-1" tabindex="-1">Egenskaper <a class="header-anchor" href="#egenskaper-1" aria-label="Permalink to &quot;Egenskaper&quot;">​</a></h3><p>✅ <strong>Inget eget minne</strong> - Endast temporära variabler under exekvering ✅ <strong>Snabbare</strong> - Ingen overhead för instance DB ✅ <strong>Enklare</strong> - Ingen instansiering krävs ❌ <strong>Kan inte lagra data</strong> - Måste använda globala variabler eller DB</p><h3 id="exempel-berakningsfunktion" tabindex="-1">Exempel: Beräkningsfunktion <a class="header-anchor" href="#exempel-berakningsfunktion" aria-label="Permalink to &quot;Exempel: Beräkningsfunktion&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FUNCTION &quot;FC_ScaleValue&quot; : Real</span></span>
<span class="line"><span>{ S7_Optimized_Access := &#39;TRUE&#39; }</span></span>
<span class="line"><span>VAR_INPUT</span></span>
<span class="line"><span>    RawValue : Int;      // Råvärde (0-27648)</span></span>
<span class="line"><span>    MinScale : Real;     // Min värde (t.ex. 0.0)</span></span>
<span class="line"><span>    MaxScale : Real;     // Max värde (t.ex. 100.0)</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>VAR_TEMP</span></span>
<span class="line"><span>    Result : Real;</span></span>
<span class="line"><span>END_VAR</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BEGIN</span></span>
<span class="line"><span>    // Skalning 0-27648 till MinScale-MaxScale</span></span>
<span class="line"><span>    Result := MinScale + (RawValue / 27648.0) * (MaxScale - MinScale);</span></span>
<span class="line"><span>    &quot;FC_ScaleValue&quot; := Result;</span><span>  // Returvärde</span></span>
<span class="line"><span>END_FUNCTION</span></span></code></pre></div><h3 id="anrop-av-fc" tabindex="-1">Anrop av FC <a class="header-anchor" href="#anrop-av-fc" aria-label="Permalink to &quot;Anrop av FC&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// I OB1:</span></span>
<span class="line"><span>#Temperature := &quot;FC_ScaleValue&quot;(</span></span>
<span class="line"><span>    RawValue := %IW64,      // Analog ingång</span></span>
<span class="line"><span>    MinScale := 0.0,</span></span>
<span class="line"><span>    MaxScale := 100.0</span></span>
<span class="line"><span>);</span></span></code></pre></div><h3 id="nar-ska-du-anvanda-fc" tabindex="-1">När ska du använda FC? <a class="header-anchor" href="#nar-ska-du-anvanda-fc" aria-label="Permalink to &quot;När ska du använda FC?&quot;">​</a></h3><p>✅ <strong>Använd FC:</strong></p><ul><li>För matematiska beräkningar (skalning, omvandling)</li><li>För enkla logiska operationer (AND, OR med flera ingångar)</li><li>När inget minne behövs mellan anrop</li><li>För &quot;utility functions&quot; (hjälpfunktioner)</li></ul><h2 id="jamforelse-ob-vs-fb-vs-fc" tabindex="-1">Jämförelse: OB vs FB vs FC <a class="header-anchor" href="#jamforelse-ob-vs-fb-vs-fc" aria-label="Permalink to &quot;Jämförelse: OB vs FB vs FC&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Egenskap</th><th>OB</th><th>FB</th><th>FC</th></tr></thead><tbody><tr><td><strong>Eget minne</strong></td><td>Nej</td><td>Ja (Instance DB)</td><td>Nej</td></tr><tr><td><strong>Anropas av</strong></td><td>Operativsystem</td><td>Användaren</td><td>Användaren</td></tr><tr><td><strong>Instansiering</strong></td><td>-</td><td>Krävs</td><td>Ej nödvändig</td></tr><tr><td><strong>Timers/Counters</strong></td><td>Nej*</td><td>Ja</td><td>Nej*</td></tr><tr><td><strong>Flera instanser</strong></td><td>Nej</td><td>Ja</td><td>Nej</td></tr><tr><td><strong>Användning</strong></td><td>Ingångspunkter</td><td>Objekt med tillstånd</td><td>Enkla funktioner</td></tr></tbody></table><p>*Kan använda globala timers/counters i DB</p><h2 id="programstruktur-best-practices" tabindex="-1">Programstruktur: Best practices <a class="header-anchor" href="#programstruktur-best-practices" aria-label="Permalink to &quot;Programstruktur: Best practices&quot;">​</a></h2><h3 id="typisk-struktur" tabindex="-1">Typisk struktur <a class="header-anchor" href="#typisk-struktur" aria-label="Permalink to &quot;Typisk struktur&quot;">​</a></h3><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OB1 (Main Cycle)</span></span>
<span class="line"><span>  ├─ FB_Motor (Instans: DB_Motor1)</span></span>
<span class="line"><span>  ├─ FB_Motor (Instans: DB_Motor2)</span></span>
<span class="line"><span>  ├─ FB_Pump (Instans: DB_Pump1)</span></span>
<span class="line"><span>  └─ FC_ScaleValue (hjälpfunktion)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OB100 (Startup)</span></span>
<span class="line"><span>  └─ Initiering av variabler</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OB35 (Cyclic 100ms)</span></span>
<span class="line"><span>  └─ FB_PID_Control (Instans: DB_PID1)</span></span></code></pre></div><h3 id="design-principer" tabindex="-1">Design-principer <a class="header-anchor" href="#design-principer" aria-label="Permalink to &quot;Design-principer&quot;">​</a></h3><p>✅ <strong>Håll OB:er korta</strong> - Anropa FB/FC istället för att skriva all logik i OB1 ✅ <strong>Använd FB för objekt</strong> - Motor, ventil, pump, etc. ✅ <strong>Använd FC för hjälpfunktioner</strong> - Skalning, omvandling, matematik ✅ <strong>Strukturera i bibliotek</strong> - Gruppera liknande FB/FC</p><h3 id="exempel-motor-objekt-med-fc-hjalp" tabindex="-1">Exempel: Motor-objekt med FC-hjälp <a class="header-anchor" href="#exempel-motor-objekt-med-fc-hjalp" aria-label="Permalink to &quot;Exempel: Motor-objekt med FC-hjälp&quot;">​</a></h3><div class="language-scl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// OB1:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Skala hastighetsvärde från HMI (0-100%) till omriktare (0-16384)</span></span>
<span class="line"><span>#SpeedScaled := &quot;FC_ScaleValue&quot;(</span></span>
<span class="line"><span>    RawValue := &quot;HMI_Speed&quot;,</span></span>
<span class="line"><span>    MinScale := 0.0,</span></span>
<span class="line"><span>    MaxScale := 16384.0</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Styr motor med FB</span></span>
<span class="line"><span>&quot;DB_Motor1&quot;(</span></span>
<span class="line"><span>    Start := &quot;HMI_Start&quot;,</span></span>
<span class="line"><span>    Stop := &quot;HMI_Stop&quot;,</span></span>
<span class="line"><span>    Speed := INT_TO_INT(#SpeedScaled)</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Kopiera resultat till utgångar</span></span>
<span class="line"><span>%Q0.0 := &quot;DB_Motor1&quot;.Running;</span></span></code></pre></div><h2 id="resurser-och-dokumentation" tabindex="-1">Resurser och dokumentation <a class="header-anchor" href="#resurser-och-dokumentation" aria-label="Permalink to &quot;Resurser och dokumentation&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/ww/en/view/90885040" target="_blank" rel="noreferrer">S7-1200 Programming Guideline</a> - Best practices</li><li><a href="https://support.industry.siemens.com/cs/document/36932465" target="_blank" rel="noreferrer">STEP 7 Help: Blocks</a> - Detaljerad blockdokumentation</li></ul><h3 id="video-tutorials" tabindex="-1">Video-tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video-tutorials&quot;">​</a></h3><ul><li>YouTube: &quot;TIA Portal OB FB FC explained&quot;</li><li>YouTube: &quot;TIA Portal function blocks tutorial&quot;</li><li>YouTube: &quot;S7-1200 program structure best practices&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">Nästa steg</p><p>Lär dig mer om programmeringsspråken <a href="./sprak-lad-fbd-scl.html">LAD, FBD, SCL</a> för att skriva kod i dessa block.</p></div>`,65)])])}const h=n(r,[["render",l]]);export{g as __pageData,h as default};
